import{_ as p,a0 as i,w as a,s as l,ao as u,I as s,x as o,a1 as e,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux 有问必答：如何在 Linux 中统计一个进程的线程数 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在 Linux 中统计一个进程的线程数 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在 Linux 中统计一个进程的线程数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在 Linux 中统计一个进程的线程数 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux","title":"Linux 有问必答：如何在 Linux 中统计一个进程的线程数","tag":"201509","desc":""},"relativePath":"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux.md","filePath":"[post].md"}'),d={name:"201509/20150817 Linux FAQs with Answers--How to count the number of threads in a process on Linux.md"};function x(m,t,f,L,g,h){const n=i("Link");return a(),l("div",null,[t[16]||(t[16]=u(`<h1 id="linux-有问必答-如何在-linux-中统计一个进程的线程数" tabindex="-1">Linux 有问必答：如何在 Linux 中统计一个进程的线程数 <a class="header-anchor" href="#linux-有问必答-如何在-linux-中统计一个进程的线程数" aria-label="Permalink to “Linux 有问必答：如何在 Linux 中统计一个进程的线程数”">​</a></h1><blockquote><p><strong>问题</strong>: 我正在运行一个程序，它在运行时会派生出多个线程。我想知道程序在运行时会有多少线程。在 Linux 中检查进程的线程数最简单的方法是什么？</p></blockquote><p>如果你想看到 Linux 中每个进程的线程数，有以下几种方法可以做到这一点。</p><h3 id="方法一-proc" tabindex="-1">方法一: /proc <a class="header-anchor" href="#方法一-proc" aria-label="Permalink to “方法一: /proc”">​</a></h3><p>proc 伪文件系统，它驻留在 /proc 目录，这是最简单的方法来查看任何活动进程的线程数。 /proc 目录以可读文本文件形式输出，提供现有进程和系统硬件相关的信息如 CPU、中断、内存、磁盘等等.</p><pre><code>$ cat /proc/&lt;pid&gt;/status
</code></pre><p>上面的命令将显示进程 <code>&lt;pid&gt;</code> 的详细信息，包括过程状态（例如, sleeping, running)，父进程 PID，UID，GID，使用的文件描述符的数量，以及上下文切换的数量。输出也包括<strong>进程创建的总线程数</strong>如下所示。</p><pre><code>Threads: &lt;N&gt;
</code></pre><p>例如，检查 PID 20571进程的线程数：</p><pre><code>$ cat /proc/20571/status
</code></pre><p><img src="https://farm6.staticflickr.com/5649/20341236279_f4a4d809d2_b.jpg" alt=""></p><p>输出表明该进程有28个线程。</p><p>或者，你可以在 <code>/proc/&lt;pid&gt;/task</code> 中简单的统计子目录的数量，如下所示。</p><pre><code>$ ls /proc/&lt;pid&gt;/task | wc
</code></pre><p>这是因为，对于一个进程中创建的每个线程，在 <code>/proc/&lt;pid&gt;/task</code> 中会创建一个相应的目录，命名为其线程 ID。由此在 <code>/proc/&lt;pid&gt;/task</code> 中目录的总数表示在进程中线程的数目。</p><h3 id="方法二-ps" tabindex="-1">方法二: ps <a class="header-anchor" href="#方法二-ps" aria-label="Permalink to “方法二: ps”">​</a></h3><p>如果你是功能强大的 ps 命令的忠实用户，这个命令也可以告诉你一个进程（用“H”选项）的线程数。下面的命令将输出进程的线程数。“h”选项需要放在前面。</p><pre><code>$ ps hH p &lt;pid&gt; | wc -l
</code></pre>`,18)),s("p",null,[t[1]||(t[1]=o("如果你想监视一个进程的不同线程消耗的硬件资源（CPU & memory），请参阅",-1)),e(n,{href:"https://linux.cn/article-5633-1.html"},{default:r(()=>[...t[0]||(t[0]=[o("此教程",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),t[17]||(t[17]=s("hr",null,null,-1)),s("p",null,[t[4]||(t[4]=o("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/number-of-threads-process-linux.html"},{default:r(()=>[...t[3]||(t[3]=[o("http://ask.xmodulo.com/number-of-threads-process-linux.html",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=o("作者：",-1)),e(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:r(()=>[...t[5]||(t[5]=[o("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=o(" 译者：",-1)),e(n,{href:"https://github.com/strugglingyouth"},{default:r(()=>[...t[6]||(t[6]=[o("strugglingyouth",-1)])]),_:1}),t[10]||(t[10]=o(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原创翻译，",-1)),e(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[o("Linux中国",-1)])]),_:1}),t[15]||(t[15]=o(" 荣誉推出",-1))])])}const w=p(d,[["render",x]]);export{b as __pageData,w as default};
